commands.command:
mkdir release-artifact release-artifact/release
archive_name="<site-project>-site-${RELEASE_SHA}.tar.gz"
checksum_name="${archive_name}.sha256"
aws s3 cp "s3://${AWS_RELEASES_BUCKET}/releases/${RELEASE_SHA}/site.tar.gz" "release-artifact/${archive_name}" --only-show-errors
aws s3 cp "s3://${AWS_RELEASES_BUCKET}/releases/${RELEASE_SHA}/site.tar.gz.sha256" "release-artifact/${checksum_name}" --only-show-errors
node --input-type=module -e '
  import { readFileSync } from "node:fs";

  const [checksumPath, expectedArchiveName] = process.argv.slice(1);
  const contents = readFileSync(checksumPath, "utf8");
  const record = /^([a-f0-9]{64})  ([^\\/\r\n]+)\n$/.exec(contents);
  if (!record || record[0] !== contents || record[2] !== expectedArchiveName || record[2] === "." || record[2] === "..") {
    console.error("Release checksum must contain exactly one producer-format record for the requested archive.");
    process.exit(1);
  }
' "release-artifact/${checksum_name}" "$archive_name"
(cd release-artifact && shasum -a 256 -c "$checksum_name" && tar -xzf "$archive_name" -C release)
